"""Private object storage. Keys are generated by the server; clients only get short-lived signed URLs."""
from __future__ import annotations

import base64
import hashlib
import hmac
import json
import os
import shutil
import time
import uuid
from pathlib import Path
from typing import BinaryIO, Iterator, Protocol

from .config import get_settings


def new_key(kind: str, owner_id: uuid.UUID | None, ext: str) -> str:
    owner = str(owner_id) if owner_id else "platform"
    safe_ext = ext if ext.isalnum() and len(ext) <= 5 else "bin"
    return f"{kind}/{owner}/{uuid.uuid4()}.{safe_ext}"


class Storage(Protocol):
    def put_file(self, key: str, path: str, content_type: str) -> None: ...
    def put_stream(self, key: str, stream: BinaryIO, content_type: str) -> None: ...
    def get_to_file(self, key: str, path: str) -> None: ...
    def local_path(self, key: str) -> str | None: ...
    def exists(self, key: str) -> bool: ...
    def size(self, key: str) -> int: ...
    def delete(self, key: str) -> None: ...
    def signed_get_url(self, key: str, filename: str, content_type: str, ttl: int | None = None) -> str: ...
    def sha256(self, key: str) -> str: ...
    def ping(self) -> None: ...
    def iter_keys(self, prefix: str = "") -> Iterator[tuple[str, int]]: ...


def _sign(payload: dict) -> str:
    raw = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode()).decode().rstrip("=")
    sig = hmac.new(get_settings().secret_key.encode(), raw.encode(), hashlib.sha256).hexdigest()[:32]
    return f"{raw}.{sig}"


def verify_signed(token: str) -> dict | None:
    try:
        raw, sig = token.rsplit(".", 1)
    except ValueError:
        return None
    exp_sig = hmac.new(get_settings().secret_key.encode(), raw.encode(), hashlib.sha256).hexdigest()[:32]
    if not hmac.compare_digest(sig, exp_sig):
        return None
    pad = "=" * (-len(raw) % 4)
    payload = json.loads(base64.urlsafe_b64decode(raw + pad))
    if payload.get("exp", 0) < time.time():
        return None
    return payload


class LocalStorage:
    """Filesystem backend for demo/test. Files are served only via HMAC-signed, expiring URLs."""

    def __init__(self, root: str):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _p(self, key: str) -> Path:
        p = (self.root / key).resolve()
        if self.root not in p.parents:
            raise ValueError("invalid key")
        return p

    def put_file(self, key: str, path: str, content_type: str) -> None:
        dst = self._p(key)
        dst.parent.mkdir(parents=True, exist_ok=True)
        tmp = dst.with_suffix(dst.suffix + ".part")
        shutil.copyfile(path, tmp)
        os.replace(tmp, dst)

    def put_stream(self, key: str, stream: BinaryIO, content_type: str) -> None:
        dst = self._p(key)
        dst.parent.mkdir(parents=True, exist_ok=True)
        tmp = dst.with_suffix(dst.suffix + ".part")
        with open(tmp, "wb") as fh:
            shutil.copyfileobj(stream, fh, 1024 * 1024)
        os.replace(tmp, dst)

    def get_to_file(self, key: str, path: str) -> None:
        shutil.copyfile(self._p(key), path)

    def local_path(self, key: str) -> str | None:
        return str(self._p(key))

    def exists(self, key: str) -> bool:
        return self._p(key).exists()

    def size(self, key: str) -> int:
        return self._p(key).stat().st_size

    def delete(self, key: str) -> None:
        try:
            self._p(key).unlink()
        except FileNotFoundError:
            pass

    def signed_get_url(self, key: str, filename: str, content_type: str, ttl: int | None = None) -> str:
        ttl = ttl or get_settings().signed_url_ttl_seconds
        tok = _sign({"k": key, "exp": int(time.time()) + ttl, "ct": content_type, "fn": filename})
        return f"/api/v1/files/{tok}"

    def sha256(self, key: str) -> str:
        h = hashlib.sha256()
        with open(self._p(key), "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                h.update(chunk)
        return h.hexdigest()

    def ping(self) -> None:
        if not os.access(self.root, os.W_OK):
            raise OSError("storage root is not writable")

    def iter_keys(self, prefix: str = ""):
        for p in sorted(self.root.rglob("*")):
            if p.is_file() and not p.name.endswith(".part"):
                key = p.relative_to(self.root).as_posix()
                if key.startswith(prefix):
                    yield key, p.stat().st_size


class S3Storage:
    """S3-compatible private bucket: SeaweedFS in the compose `s3` profile, or any external S3 service.

    The bucket is never exposed: objects reach browsers only through the API after a short-lived signed token.
    """

    def __init__(self):
        import boto3
        from botocore.config import Config
        s = get_settings()
        self.bucket = s.s3_bucket
        self.client = boto3.client(
            "s3", endpoint_url=s.s3_endpoint_url, aws_access_key_id=s.s3_access_key,
            aws_secret_access_key=s.s3_secret_key, region_name=s.s3_region,
            config=Config(s3={"addressing_style": "path"}, retries={"max_attempts": 4, "mode": "standard"},
                          connect_timeout=5, read_timeout=60,
                          # SeaweedFS/older S3 servers reject the new default CRC32 trailers on uploads
                          request_checksum_calculation="when_required",
                          response_checksum_validation="when_required"))
        self._bucket_ready = False

    def ensure_bucket(self) -> None:
        """Create the bucket when missing (first start) and refuse to run on a publicly readable bucket."""
        if self._bucket_ready:
            return
        from botocore.exceptions import ClientError, EndpointConnectionError
        missing = False
        for attempt in range(30):  # the bundled S3 server may still be starting together with the stack
            try:
                self.client.head_bucket(Bucket=self.bucket)
                break
            except EndpointConnectionError:
                if attempt == 29:
                    raise
                time.sleep(2)
            except ClientError as e:
                if e.response.get("Error", {}).get("Code") not in ("404", "NoSuchBucket", "NotFound"):
                    raise
                missing = True
                break
        if missing:
            kw = {"Bucket": self.bucket}
            if get_settings().s3_region not in ("", "us-east-1"):
                kw["CreateBucketConfiguration"] = {"LocationConstraint": get_settings().s3_region}
            self.client.create_bucket(**kw)
        if self.public_policy():
            raise RuntimeError(f"bucket {self.bucket} has a public policy; storage must stay private")
        self._bucket_ready = True

    def public_policy(self) -> bool:
        """True when a bucket policy grants anything to everyone (Principal "*")."""
        from botocore.exceptions import ClientError
        try:
            pol = json.loads(self.client.get_bucket_policy(Bucket=self.bucket)["Policy"])
        except ClientError:
            return False  # no policy (or the server has no policy API): private by default
        for st in pol.get("Statement", []):
            pr = st.get("Principal")
            if st.get("Effect") == "Allow" and (pr == "*" or (isinstance(pr, dict) and pr.get("AWS") in ("*", ["*"]))):
                return True
        return False

    def ping(self) -> None:
        self.ensure_bucket()

    def sha256(self, key):
        h = hashlib.sha256()
        body = self.client.get_object(Bucket=self.bucket, Key=key)["Body"]
        for chunk in body.iter_chunks(1 << 20):
            h.update(chunk)
        return h.hexdigest()

    def iter_keys(self, prefix=""):
        for page in self.client.get_paginator("list_objects_v2").paginate(Bucket=self.bucket, Prefix=prefix):
            for o in page.get("Contents", []):
                yield o["Key"], int(o["Size"])

    def put_file(self, key, path, content_type):
        self.client.upload_file(path, self.bucket, key, ExtraArgs={"ContentType": content_type})

    def put_stream(self, key, stream, content_type):
        self.client.upload_fileobj(stream, self.bucket, key, ExtraArgs={"ContentType": content_type})

    def get_to_file(self, key, path):
        self.client.download_file(self.bucket, key, path)

    def local_path(self, key):
        return None

    def exists(self, key):
        try:
            self.client.head_object(Bucket=self.bucket, Key=key)
            return True
        except Exception:
            return False

    def size(self, key):
        return int(self.client.head_object(Bucket=self.bucket, Key=key)["ContentLength"])

    def delete(self, key):
        self.client.delete_object(Bucket=self.bucket, Key=key)

    def signed_get_url(self, key, filename, content_type, ttl=None):
        # The bucket stays on the internal network; the API streams objects after verifying a short-lived token.
        ttl = ttl or get_settings().signed_url_ttl_seconds
        tok = _sign({"k": key, "exp": int(time.time()) + ttl, "ct": content_type, "fn": filename})
        return f"/api/v1/files/{tok}"

    def open_range(self, key, range_header: str | None):
        kw = {"Bucket": self.bucket, "Key": key}
        if range_header:
            kw["Range"] = range_header
        obj = self.client.get_object(**kw)
        return obj["Body"], obj.get("ContentRange"), int(obj["ContentLength"])


_storage: Storage | None = None


def get_storage() -> Storage:
    global _storage
    if _storage is None:
        s = get_settings()
        if s.storage_backend == "s3":
            st = S3Storage()
            st.ensure_bucket()
            _storage = st
        else:
            _storage = LocalStorage(s.storage_root)
    return _storage


def reset_storage() -> None:
    global _storage
    _storage = None
